export function translator(language){return (key,args={})=>(copy[language]?.[key]??copy.en[key]??key).replace(/\{(\w+)\}/g,(_,k)=>String(args[k]??''));}
export function lessonText(lesson,field,language,side){let text=(language==='zh'?lessonChinese[lesson.id]?.[field]:null)??lesson[field];if(side==='b')text=text.replace(/[a-h][1-8]/g,s=>s[0]+(9-Number(s[1]))).replace(/Black/g,'White').replace(/black/g,'white').replace(/eighth rank/g,'first rank').replace(/第八横线/g,'第一横线');return text;}
